class Solution {
    int height(TreeNode* node) {
        if (!node) return 0;
        return 1 + std::max(height(node->left), height(node->right));
    }
    void place(TreeNode* node, int row, int left, int right,
               std::vector<std::vector<std::string>>& ans) {
        if (!node || left > right) return;
        int mid = left + (right - left) / 2;
        ans[row][mid] = std::to_string(node->val);
        place(node->left, row + 1, left, mid - 1, ans);
        place(node->right, row + 1, mid + 1, right, ans);
    }
public:
    std::vector<std::vector<std::string>> printTree(TreeNode* root) {
        int h = height(root);
        int cols = (1 << h) - 1;
        std::vector<std::vector<std::string>> ans(h,
            std::vector<std::string>(cols, ""));
        place(root, 0, 0, cols - 1, ans);
        return ans;
    }
};
